    "code": "import React, { useState, ChangeEvent } from \"react\";\n\ntype FormData = { name: string; email: string; phone: string; city: string };\n\nexport default function App() {\n  const [form, setForm] = useState<FormData>({ name:\"\", email:\"\", phone:\"\", city:\"\" });\n  function handleChange(e: ChangeEvent<HTMLInputElement>) {\n    const { name, value } = e.target;\n    setForm(prev => ({ ...prev, [name]: value }));\n  }\n  return (\n    <div className=\"p-3 border rounded bg-white\">\n      <h6>Single object state</h6>\n      {([\"name\",\"email\",\"phone\",\"city\"] as (keyof FormData)[]).map(k => (\n        <input key={k} name={k} value={form[k]} onChange={handleChange} className=\"form-control mb-2\" placeholder={k} />\n      ))}\n      <pre className=\"bg-light p-2 mb-0 small\">{JSON.stringify(form,null,2)}</pre>\n    </div>\n  );\n}\n"
