    "code": "import React, { useState, ChangeEvent } from \"react\";\n\ninterface UserForm { username: string; email: string; age?: number; bio?: string; }\ntype Role = \"user\" | \"admin\";\ntype Profile = UserForm & { role: Role };\n\nconst initial: Profile = { username:\"\", email:\"\", role:\"user\" };\nconst preset: Profile = { username:\"aayush\", email:\"a@b.com\", age:22, bio:\"Dev\", role:\"admin\" };\n\nexport default function App() {\n  const [form, setForm] = useState<Profile>(preset);\n  const on = (e: ChangeEvent<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>) => {\n    const { name, value } = e.target;\n    setForm(p => ({ ...p, [name]: name===\"age\" ? (value? Number(value): undefined) : value } as Profile));\n  };\n  return (\n    <div className=\"p-3 border rounded bg-white\">\n      <h6>Interface/type + optional + defaults</h6>\n      <input name=\"username\" value={form.username} onChange={on} className=\"form-control mb-2\" placeholder=\"username\" />\n      <input name=\"email\" value={form.email} onChange={on} className=\"form-control mb-2\" placeholder=\"email\" />\n      <input name=\"age\" type=\"number\" value={form.age ?? \"\"} onChange={on} className=\"form-control mb-2\" placeholder=\"age (optional)\" />\n      <textarea name=\"bio\" value={form.bio ?? \"\"} onChange={on} className=\"form-control mb-2\" placeholder=\"bio (optional)\" />\n      <select name=\"role\" value={form.role} onChange={on} className=\"form-select mb-2\"><option value=\"user\">user</option><option value=\"admin\">admin</option></select>\n      <div className=\"d-flex gap-2 mb-2\"><button className=\"btn btn-sm btn-outline-secondary\" onClick={()=>setForm(initial)}>Empty</button><button className=\"btn btn-sm btn-outline-secondary\" onClick={()=>setForm(preset)}>Preset</button></div>\n      <pre className=\"bg-light p-2 mb-0 small\">{JSON.stringify(form,null,2)}</pre>\n    </div>\n  );\n}\n"
