    "code": "import React, { useState, ChangeEvent } from \"react\";\n\nexport default function App() {\n  const [f,setF]=useState({date:\"\",time:\"\",dt:\"\",month:\"\",week:\"\",start:\"\",end:\"\"});\n  const on=(e:ChangeEvent<HTMLInputElement>)=>setF(p=>({...p,[e.target.name]:e.target.value}));\n  const bad = f.start && f.end && f.start > f.end;\n  return <div className=\"p-3 border rounded bg-white\"><div className=\"row g-2\">\n    <div className=\"col-md-4\"><label className=\"form-label\">Date</label><input name=\"date\" type=\"date\" value={f.date} onChange={on} className=\"form-control\" /></div>\n    <div className=\"col-md-4\"><label className=\"form-label\">Time</label><input name=\"time\" type=\"time\" value={f.time} onChange={on} className=\"form-control\" /></div>\n    <div className=\"col-md-4\"><label className=\"form-label\">Datetime-local</label><input name=\"dt\" type=\"datetime-local\" value={f.dt} onChange={on} className=\"form-control\" /></div>\n    <div className=\"col-md-6\"><label className=\"form-label\">Month</label><input name=\"month\" type=\"month\" value={f.month} onChange={on} className=\"form-control\" /></div>\n    <div className=\"col-md-6\"><label className=\"form-label\">Week</label><input name=\"week\" type=\"week\" value={f.week} onChange={on} className=\"form-control\" /></div>\n    <div className=\"col-md-6\"><label className=\"form-label\">Start</label><input name=\"start\" type=\"date\" value={f.start} onChange={on} className={`form-control ${bad?\"is-invalid\":\"\"}`} /></div>\n    <div className=\"col-md-6\"><label className=\"form-label\">End</label><input name=\"end\" type=\"date\" value={f.end} onChange={on} className={`form-control ${bad?\"is-invalid\":\"\"}`} />{bad&&<div className=\"invalid-feedback\">End must be ≥ start</div>}</div>\n  </div><pre className=\"bg-light p-2 mt-3 mb-0 small\">{JSON.stringify(f,null,2)}</pre></div>;\n}\n"
